const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE = 0.1;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => {
    const basePremium = step.items.length * SWORD_BASE_PREMIUM;
    const premium =
      basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;

    return { premium };
  });

  return { results };
};

