import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case and base premiums ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("a single sword → base premium 100 G, plus 10 G first insurance and 5 G fee → 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("a single amulet → base premium 60 G → premium 71 G");
  it.todo("a single staff → base premium 80 G → premium 93 G");
  it.todo("a single potion → base premium 40 G → premium 49 G");

  // --- Components and the building block of 3 alike ---
  it.todo("1 rune → base premium 25 G");
  it.todo("2 runes → 50 G base premium (no block)");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds a 50 % surcharge on that item's base premium");
  it.todo("sword with exactly enchantment 5 → 30 % high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
  it.todo(
    "policy with a cursed sword and a plain amulet → base 160 G, curse surcharge 50 G (item-scoped) → 210 G before further modifiers and fee",
  );

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year → no loyalty discount");
  it.todo("each item in a quote carries the 10 % first insurance surcharge");
  it.todo("the second quote of a customer receives a 15 % follow-up contract discount");
  it.todo("a 5 G processing fee is added to every premium");

  // --- Rounding ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword (0 years, no previous contract) → premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");

  // --- Claims: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claims: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claims: deductible per damage event ---
  it.todo("a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Claims: insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects the premium only)");
  it.todo("two successive claims of 1500 G on a sword → payout 1400 G (cap remaining 600 G), then payout 600 G (cap remaining 0 G)");

  // --- Claims: multiple items of the same type ---
  it.todo("two sword damage entries against a policy covering two swords → each entry gets its own deductible");

  // --- Errors ---
  it.todo("quote with an unknown item type (e.g. broomstick) → error");
  it.todo("claim referencing an item not part of the policy (amulet damaged when only a sword is insured) → error");
  it.todo("claim with more damage entries of a type than the policy covers → error");
  it.todo("claim with a damage entry with amount -200 → error");

  // --- CLI ---
  it.todo("the CLI reads a scenario JSON from stdin and writes {\"results\": [...]} to stdout");
  it.todo("the CLI exits with a non-zero status code and writes an error description to stderr on an invalid scenario");
});

