export type Item = {
  type: string;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
};

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const quotePremium = (items: Item[]): number => {
  const basePremium = sum(items.map(basePremiumOf));
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;

  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

