export type Item = {
  type: string;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const totalBasePremiumOf = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item), 0);

const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const quotePremium = (items: Item[]): number => {
  const basePremium = totalBasePremiumOf(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return roundedInMHPCOsFavour(
    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

