export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const alikeItemGroups = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

const basePremiumOfGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : group.reduce((total, item) => total + basePremiumOf(item), 0);

const totalBasePremiumOf = (items: Item[]): number =>
  alikeItemGroups(items).reduce(
    (total, group) => total + basePremiumOfGroup(group),
    0,
  );

const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const CURSE_SURCHARGE_RATE = 0.5;

type ItemSurchargeRule = {
  appliesTo: (item: Item) => boolean;
  rate: number;
};

const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
];

const surchargeOf = (item: Item): number =>
  ITEM_SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
    (total, rule) => total + basePremiumOf(item) * rule.rate,
    0,
  );

const totalItemSurchargeOf = (items: Item[]): number =>
  items.reduce((total, item) => total + surchargeOf(item), 0);

const quotePremium = (items: Item[]): number => {
  const basePremium = totalBasePremiumOf(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return roundedInMHPCOsFavour(
    basePremium +
      totalItemSurchargeOf(items) +
      firstInsuranceSurcharge +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

