const FOLLOW_UP_DISCOUNT_RATE = -0.15;

type Contract = {
  customer: Customer;
  previousContracts: number;
};

const POLICY_MODIFIER_RULES: Rule<Contract>[] = [
  {
    appliesTo: ({ customer }) =>
      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
    rate: LOYALTY_DISCOUNT_RATE,
  },
  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
  {
    appliesTo: ({ previousContracts }) => previousContracts > 0,
    rate: FOLLOW_UP_DISCOUNT_RATE,
  },
];

const quotePremium = (items: Item[], contract: Contract): number => {
  const basePremium = totalBasePremiumOf(items);

  return roundedInMHPCOsFavour(
    basePremium +
      totalItemSurchargeOf(items) +
      basePremium * totalRateOf(POLICY_MODIFIER_RULES, contract) +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  let previousContracts = 0;

  return {
    results: scenario.steps.map((step) => {
      const premium = quotePremium(step.items, {
        customer: scenario.customer,
        previousContracts,
      });
      previousContracts += 1;

      return { premium };
    }),
  };
};

