export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type ClaimStep = {
  op: "claim";
  policy: number;
  incident: Incident;
};

export type Step = QuoteStep | ClaimStep;

export type Customer = {
  yearsWithMHPCO: number;
};

export type Scenario = {
  customer: Customer;
  steps: Step[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const alikeItemGroups = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groupsByType, item) =>
        groupsByType.set(item.type, [
          ...(groupsByType.get(item.type) ?? []),
          item,
        ]),
      new Map<string, Item[]>(),
    )
    .values(),
];

const basePremiumOfGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : group.reduce((total, item) => total + basePremiumOf(item), 0);

const totalBasePremiumOf = (items: Item[]): number =>
  alikeItemGroups(items).reduce(
    (total, group) => total + basePremiumOfGroup(group),
    0,
  );

const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

type Rule<Subject> = {
  appliesTo: (subject: Subject) => boolean;
  rate: number;
};

const totalRateOf = <Subject,>(
  rules: Rule<Subject>[],
  subject: Subject,
): number =>
  rules.reduce(
    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
    0,
  );

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
  },
];

const itemSurchargeOf = (item: Item): number =>
  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);

const totalItemSurchargeOf = (items: Item[]): number =>
  items.reduce((total, item) => total + itemSurchargeOf(item), 0);

const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = -0.2;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const FOLLOW_UP_DISCOUNT_RATE = -0.15;

type PolicyContext = {
  customer: Customer;
  previousContracts: number;
};

const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
  {
    appliesTo: ({ customer }) =>
      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
    rate: LOYALTY_DISCOUNT_RATE,
  },
  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
  {
    appliesTo: ({ previousContracts }) => previousContracts > 0,
    rate: FOLLOW_UP_DISCOUNT_RATE,
  },
];

const quotePremium = (items: Item[], policy: PolicyContext): number => {
  const basePremium = totalBasePremiumOf(items);

  return roundedUpInMHPCOsFavour(
    basePremium +
      totalItemSurchargeOf(items) +
      basePremium * totalRateOf(POLICY_MODIFIER_RULES, policy) +
      PROCESSING_FEE,
  );
};

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

