type ClaimResult = {
  payout: number;
  remainingCap: number;
};

const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item =>
  insuredItems.find((item) => item.type === damage.itemType) as Item;

const totalPayoutFor = (damages: Damage[], insuredItems: Item[]): number =>
  damages.reduce(
    (total, damage) =>
      total + payoutForDamage(damage, insuredItemFor(damage, insuredItems)),
    0,
  );

const settleClaim = (incident: Incident, insuredItems: Item[]): ClaimResult => {
  const payout = totalPayoutFor(incident.damages, insuredItems);

  return { payout, remainingCap: payoutCapOf(insuredItems) - payout };
};

