type IssuedPolicy = {
  stepIndex: number;
  insuredItems: Item[];
};

// Everything a step needs to know about the steps that came before it.
type ScenarioHistory = {
  issuedPolicies: IssuedPolicy[];
  results: unknown[];
};

const EMPTY_HISTORY: ScenarioHistory = { issuedPolicies: [], results: [] };

const insuredItemsOfPolicy = (
  issuedPolicies: IssuedPolicy[],
  policyIndex: number,
): Item[] =>
  issuedPolicies.find((policy) => policy.stepIndex === policyIndex)
    ?.insuredItems ?? [];

const withStepAppended = (
  history: ScenarioHistory,
  issuedPolicies: IssuedPolicy[],
  result: unknown,
): ScenarioHistory => ({
  issuedPolicies,
  results: [...history.results, result],
});

const takeQuoteStep = (
  step: QuoteStep,
  stepIndex: number,
  history: ScenarioHistory,
  customer: Customer,
): ScenarioHistory =>
  withStepAppended(
    history,
    [...history.issuedPolicies, { stepIndex, insuredItems: step.items }],
    {
      premium: quotePremium(step.items, {
        customer,
        previousContracts: history.issuedPolicies.length,
      }),
    },
  );

const takeClaimStep = (
  step: ClaimStep,
  history: ScenarioHistory,
): ScenarioHistory =>
  withStepAppended(
    history,
    history.issuedPolicies,
    settleClaim(
      step.incident,
      insuredItemsOfPolicy(history.issuedPolicies, step.policy),
    ),
  );

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const history = scenario.steps.reduce(
    (soFar, step, stepIndex) =>
      isQuote(step)
        ? takeQuoteStep(step, stepIndex, soFar, scenario.customer)
        : takeClaimStep(step, soFar),
    EMPTY_HISTORY,
  );

  return { results: history.results };
};

